use tokio::sync::Notify;

#[path = "root_authority_session_final_retirement.rs"]
mod final_retirement;
pub(crate) use final_retirement::OriginalRootSessionFullyRetired;

/// Recheck the stored results of the actual joins after ordinary phase
/// admission has closed. Only the consumed paused-purpose cap supplies
/// this expected observation; no counter alone creates that capability.
pub(in super::super) fn require_original_joined_summary(
    &self,
    expected: &OriginalConsumerJoinSummary,
) -> Result<(), AgentdRootAuthorityError> {
    let state = self.state.lock().map_err(|_| {
        self.gate.close();
        AgentdRootAuthorityError::Unavailable
    })?;
    let actual = OriginalConsumerJoinSummary {
        registered: state.registered,
        joined: state.joined,
        first_observed_failure: state.first_observed_failure,
        admission_poisoned: false,
    };
    if !state.stopped || !state.retained.is_empty()
        || state.worker_failure.is_some()
        || actual != *expected
        || actual.registered != actual.joined
        || actual.first_observed_failure.is_some()
        || expected.admission_poisoned
    {
        return Err(AgentdRootAuthorityError::Unavailable);
    }
    Ok(())
}

